long long comb(int w, int i) { // 计算组合数C(w,i)
    if (i < 0 || i > w) {
        return 0;
    }
    long long res = 1;
    for (int t = 1; t <= i; ++t) {
        res = res * (w t + 1) / t;
    }
    return res;
}
long long count_patterns(int w, int k) { // 计算长度为w、1的个数≤k的码字总数
    long long total = 0;
    for (int t = 0; t <= min(w, k); ++t) {
        total += comb(w, t);
    }
    return total;
}
